// Набір живе окремим модулем: його читають і контакти, які цей файл сам
// імпортує, — тримати його тут означало б коло в імпортах.
const EMPTY_VALUES = EMPTY_PLACEHOLDER_VALUES;

// Поточне значення поля тут не своє: правило одне на весь застосунок і живе в
// `getCurrentValue` — масив у полі це історія, і поточне в ній останнє. Свій
// обхід тут був, і відрізнявся він рівно тим, що пропускав порожні версії, тож
// стертий контакт картка показувала далі.

export const normalizeDisplayValue = value => {
  const current = getCurrentValue(value);
  if (Array.isArray(current)) {
    return current.map(normalizeDisplayValue).filter(Boolean).join(', ');
  }
  if (current && typeof current === 'object') {
    return Object.values(current).map(normalizeDisplayValue).filter(Boolean).join(', ');
  }
  if (current === null || current === undefined) return '';
  const normalized = String(current).trim();
  if (!normalized || EMPTY_VALUES.has(normalized.toLowerCase())) return '';
  return normalized;
};

export const shouldRenderField = value => Boolean(normalizeDisplayValue(value));

// «+» — так записано «так» у старих анкетах з адмінки. Фільтр стрічки давно
// читає його як «заміжня» (`toMaritalStatusCategory`), а картка показувала
// голий плюс: «Сімейний стан: +». Мінус окремо не потрібен — для показу він
// заглушка порожнього поля (`EMPTY_PLACEHOLDER_VALUES`).
const YES_TOKENS = new Set(['yes', 'true', '+']);
const NO_TOKENS = new Set(['no', 'false']);

// Відповідь «так/ні» рахує застосунок, а не вводить людина, — тож і мова в неї
// та сама, що й у підпису поруч. Раніше вона була жорстко українською, і в
// англійському інтерфейсі виходило «Own kids: є».
const yesNoLabel = (rawValue, kind, language) => {
  const normalized = normalizeDisplayValue(rawValue).toLowerCase();
  if (!normalized) return '';
  const [yesText, noText] = derivedValueTexts(kind, language);
  if (YES_TOKENS.has(normalized)) return yesText;
  if (NO_TOKENS.has(normalized)) return noText;
  // Значення, введене людиною («вдова», «цивільний шлюб»), лишається як є:
  // перекладати вміст анкети — це вже не підстановка, а редагування.
  return normalizeDisplayValue(rawValue);
};

export const maritalStatusLabel = (value, language) => yesNoLabel(value, 'marital', language);
export const glassesLabel = (value, language) => yesNoLabel(value, 'yesNo', language);
const ownKidsBooleanLabel = (value, language) => yesNoLabel(value, 'ownKids', language);

// blood is stored as one combined field ("3+", "2", "+", "AB-", roman numerals,
// Ukrainian "І" instead of Latin "I", verbose Rh words, etc). Parse it into an
// ABO letter and a Rh sign so the two missing-half cases (bare sign, bare
// group) can be rendered with context instead of as a lone character.
const CYRILLIC_I_RE = /[Іі]/g;
const toLatinRoman = value => value.replace(CYRILLIC_I_RE, ch => (ch === 'І' ? 'I' : 'i'));

const ABO_LETTER_BY_TOKEN = {
  '1': 'O', i: 'O', o: 'O',
  '2': 'A', ii: 'A', a: 'A',
  '3': 'B', iii: 'B', b: 'B',
  '4': 'AB', iv: 'AB', ab: 'AB',
};
const ABO_TOKEN_RE = /^(iv|iii|ii|ab|i|a|b|o|[1-4])/i;
const RH_POSITIVE_RE = /^(rh)?\s*(\+|pos(itive)?)$/i;
const RH_NEGATIVE_RE = /^(rh)?\s*(-|neg(ative)?)$/i;

export const parseBloodValue = rawValue => {
  const trimmed = toLatinRoman(String(rawValue ?? '').trim());
  if (!trimmed) return { abo: '', rh: '' };

  let rest = trimmed;
  let abo = '';
  const aboMatch = rest.match(ABO_TOKEN_RE);
  if (aboMatch) {
    abo = ABO_LETTER_BY_TOKEN[aboMatch[1].toLowerCase()] || '';
    rest = rest.slice(aboMatch[0].length).trim();
  }

  let rh = '';
  const rhCandidate = rest.replace(/−/g, '-').trim();
  if (rhCandidate) {
    if (RH_POSITIVE_RE.test(rhCandidate)) rh = '+';
    else if (RH_NEGATIVE_RE.test(rhCandidate)) rh = '-';
  }

  return { abo, rh };
};

export const formatBloodGroup = (abo, rh) => {
  const sign = rh === '+' ? '+' : rh === '-' ? '−' : '';
  if (abo && sign) return `${abo}${sign}`;
  if (abo) return abo;
  if (sign) return `Rh${sign}`;
  return null;
};

export const getBloodGroupDisplay = user => {
  const { abo, rh } = parseBloodValue(normalizeDisplayValue(user?.blood));
  return formatBloodGroup(abo, rh);
};

export const getProfileRole = user => {
  const role = normalizeDisplayValue(user?.role || user?.userRole).toLowerCase();
  const normalizedRole = normalizeProfileRole(role);
  if (normalizedRole) return normalizedRole;
  return 'other';
};

export const getRoleLabel = (role, language) => {
  if (role === 'ed') return translateProfileLabel('Egg donor', language);
  if (role === 'ag') return translateProfileLabel('Agency', language);
  if (role === 'ip') return translateProfileLabel('Intended parents', language);
  if (role === 'sm') return translateProfileLabel('Surrogate mother', language);
  if (role === 'cl') return translateProfileLabel('Clinic', language);
  return translateProfileLabel('Profile', language);
};

/**
 * Дволітерний код ролі — тепер лише умова показу, а не напис.
 *
 * Показували код (`ED`, `IP`) на всіх екранах: він короткий і однаковий
 * скрізь. Але його знав лише той, хто бачив дані, — читач дивився на «IP» і
 * не знав, що це біологічні батьки. Тож скрізь пишеться слово з
 * `getRoleLabel` (той самий перелік, що й «Хто ви» — `PROFILE_ROLE_OPTIONS`,
 * — і ті самі слова в чіпі фільтра), а код лишився відповіддю на питання
 * «чи є в картки роль, яку ми вміємо назвати»: роль без коду плашки не має.
 */
const ROLE_CODES = { ed: 'ED', sm: 'SM', ip: 'IP', ag: 'AG', cl: 'CL' };

export const getRoleCode = role => ROLE_CODES[String(role || '').trim().toLowerCase()] || '';

const getEmailName = user => {
  const email = normalizeDisplayValue(user?.email);
  if (!email) return '';
  return email.split('@')[0].trim();
};

const normalizeNameKey = part => part.toLowerCase().replace(/\s+/g, ' ').trim();

const isDuplicateNameKey = (seen, key) => {
  const keyTokens = key.split(' ');

  return Array.from(seen).some(existingKey => {
    const existingTokens = existingKey.split(' ');
    return existingKey === key
      || keyTokens.every(token => existingTokens.includes(token));
  });
};

const appendUniqueNamePart = (parts, seen, part) => {
  const key = normalizeNameKey(part);
  if (!key || isDuplicateNameKey(seen, key)) return;
  seen.add(key);
  parts.push(part);
};

const getPrimaryNamePart = user => [user?.name, user?.surname]
  .map(normalizeDisplayValue)
  .filter(Boolean)
  .join(' ');

const getUniqueNameParts = user => {
  const parts = [];
  const seen = new Set();

  [getPrimaryNamePart(user), user?.nameWife, user?.nameHusband]
    .map(normalizeDisplayValue)
    .filter(Boolean)
    .forEach(part => appendUniqueNamePart(parts, seen, part));

  return parts;
};

export const getProfileName = user => {
  const name = getUniqueNameParts(user).join(' ');
  return name || getEmailName(user);
};

export const getProfileAge = user => {
  const birth = normalizeDisplayValue(user?.birth);
  if (!birth) return '';
  const age = utilCalculateAge(birth);
  return age ? String(age) : '';
};

export const getProfileLocation = (user, language) => {
  const country = normalizeCountry(normalizeDisplayValue(user?.country), language);
  const region = normalizeRegion(normalizeDisplayValue(user?.region), language);
  const city = formatCityName(normalizeDisplayValue(user?.city), resolveProfileLanguage(language));
  return [country, city || region].filter(Boolean).join(', ') || region || city;
};

// Країна, область і місто в полях картки — ті самі довідники, що й рядок
// локації вище (`utils/profileNormalization`); незнайоме лишається як є.
const countryDisplayValue = (user, language) => normalizeCountry(normalizeDisplayValue(user?.country), language);
const regionDisplayValue = (user, language) => normalizeRegion(normalizeDisplayValue(user?.region), language);
const cityDisplayValue = (user, language) => formatCityName(
  normalizeDisplayValue(user?.city),
  resolveProfileLanguage(language),
);

export const getProfilePhotos = user => {
  const rawPhotos = Array.isArray(user?.photos) ? user.photos : [user?.photos, user?.photo, user?.avatar];
  return [...new Set(rawPhotos.map(normalizeDisplayValue).filter(Boolean).map(convertDriveLinkToImage))];
};

// `resolved: true` marks getters that already return final human-readable text
// (e.g. "немає"), which must not be re-run through normalizeDisplayValue's
// EMPTY_VALUES sentinel stripping - that set exists to drop raw DB placeholders
// like "-"/"n/a", but it also happens to contain the word "немає" itself, which
// would otherwise wrongly delete an intentionally rendered "немає" answer.
const field = (key, label, valueGetter, sourceKeys, { resolved = false } = {}) => ({
  key,
  label,
  valueGetter,
  sourceKeys: sourceKeys || [key],
  resolved,
});
const valueFor = (user, item, language) => {
  if (!item.valueGetter) return normalizeDisplayValue(user?.[item.key]);
  // Мова доїжджає до самого гетера: підставлені «так/ні» рахуються тут, і
  // рахувати їх іншою мовою, ніж підпис поруч, — це і є та неузгодженість,
  // через яку в англійському макеті стояло «Own kids: є».
  const result = item.valueGetter(user, language);
  if (item.resolved) return typeof result === 'string' ? result.trim() : normalizeDisplayValue(result);
  return normalizeDisplayValue(result);
};
const isExcluded = (item, excludeKeys = []) => {
  const excluded = new Set(excludeKeys || []);
  return [item.key, ...(item.sourceKeys || [])].some(key => excluded.has(key));
};
// Значення, вибране зі списку, показується мовою інтерфейсу — пара для нього
// вже лежить у формі. Вільний текст словнику не відповідає й лишається як є.
const localizeFieldValue = (item, value, language) => {
  const lang = resolveProfileLanguage(language);
  const extra = getExtraLocale(lang);
  if (item.resolved || (lang !== 'uk' && !extra)) return value;
  const parts = String(value)
    .split(', ')
    .map(part => translateFieldValue(item.key, part, lang));
  return extra ? extra.sentences.list(parts) : parts.join(', ');
};

const toDisplayFields = (items, user, excludeKeys = [], language) =>
  items
    .filter(item => !isExcluded(item, excludeKeys))
    .map(item => {
      const value = valueFor(user, item, language);
      return {
        ...item,
        label: translateProfileLabel(item.label, language),
        value: localizeFieldValue(item, value, language),
      };
    })
    .filter(item => (item.resolved ? Boolean(item.value) : shouldRenderField(item.value)));

export const bmiValue = user => {
  const explicit = normalizeDisplayValue(user?.bmi);
  if (explicit) return explicit;
  // Із нормалізованих зросту й ваги: фути, записані як сантиметри, давали
  // «BMI 1200» і «BMI 30000». Неправдоподібного ІМТ не показуємо.
  const bmi = computeBmi(normalizeDisplayValue(user?.height), normalizeDisplayValue(user?.weight));
  return bmi ? String(bmi) : '';
};

const heightDisplayValue = user => {
  const cm = normalizeHeightCm(normalizeDisplayValue(user?.height));
  return cm ? String(cm) : '';
};
const weightDisplayValue = user => {
  const kg = normalizeWeightKg(normalizeDisplayValue(user?.weight));
  return kg ? String(kg) : '';
};

const ownKidsValue = user => {
  const raw = normalizeDisplayValue(user?.ownKids);
  const compact = raw.toLowerCase();
  if (!raw) return '';
  if (['0', 'no', 'ні', 'нет'].includes(compact)) return 'No';
  if (/^[1-9]/.test(compact) || ['yes', 'так', 'да'].includes(compact)) return 'Yes';
  return raw;
};

const ownKidsDisplayValue = (user, language) => ownKidsBooleanLabel(ownKidsValue(user), language);

// `ownKids` у формі підписане «Кількість пологів» (`formFields.js`), а звідси
// йшло через «є/немає»: анкета з одними пологами показувала «Власні діти: є»,
// і число, і сенс губились разом. Рядок стрічки те саме поле читав чесно —
// «пологів 1», — тож два екрани розходились на одному полі.
const birthsCountValue = user => normalizeDisplayValue(user?.ownKids);

// Кесарів розтин лежить під чотирма іменами в анкетах різних поколінь.
const cSectionValue = user => formatProfileCountOrDate(normalizeDisplayValue(
  user?.cSection || user?.csection || user?.c_section || user?.cesareanSection
));
const maritalStatusDisplayValue = (user, language) => maritalStatusLabel(user?.maritalStatus, language);
// «Окуляри — ні» означає «зір гарний», і саме це читач хоче знати.
const glassesDisplayValue = (user, language) => {
  const normalized = normalizeDisplayValue(user?.glasses).toLowerCase();
  if (NO_TOKENS.has(normalized) || normalized === 'ні') {
    const lang = resolveProfileLanguage(language);
    const extra = getExtraLocale(lang);
    if (extra) return extra.sentences.glasses.short;
    return lang === 'en' ? 'no, good eyesight' : 'не носить, зір хороший';
  }
  return glassesLabel(user?.glasses, language);
};

const donorExperienceValue = user => {
  const exp = normalizeDisplayValue(user?.experience || user?.donationExperience || user?.previousDonation);
  const count = normalizeDisplayValue(user?.donationCount || user?.donationsCount);
  if (exp && count) return `${exp} · ${count}`;
  return exp || count;
};

